/** Original STEP mechanics lessons; assumptions are part of each model. */
import { tex as r, technique as t, linkedProblem as q } from './admissions-authoring.js';

export const stepMechanicsContent = {
  'mechanics/motion': {
    bullets: [
      t('Free-body diagrams and model assumptions', '受力图与模型假设', '先给每个物体单独画外力，声明轻绳、光滑接触或质点假设，才能决定哪些力相同或可以忽略。', '合力按方向相加；作用力与反作用力属于不同物体。', r`\sum\mathbf F=m\mathbf a`, '选坐标与正方向，列重力、支持力、张力及摩擦；用国际单位和量纲核对每一项。', '例如光滑斜面上的支持力垂直斜面；只有没有其他法向力或法向加速度时才等于重力法向分量。', '不能把不同物体的作用反作用力放在同一张受力图上相消；轻绳等张力需要相应理想模型。'),
      t('Kinematics and signed displacement', '运动学与带符号位移', '速度是位移变化率，加速度是速度变化率；总路程需在转向位置分段。', '匀加速公式只在加速度恒定时使用。', r`v=u+at,\quad s=ut+\frac12at^2,\quad v^2=u^2+2as`, '先确认是否匀加速；变加速时从导数积分，并用初始条件确定常数。', r`速度 \(v(t)=2-t\) 在两秒处转向，因此求前三秒路程时需分段积分速度绝对值。`, '负速度不等于减速；减速取决于速度与加速度是否反向，路程也不等于位移绝对值。'),
      t('Projectile components and landing conditions', '抛体分量与落地条件', '无空气阻力且重力恒定时，水平匀速、竖直匀加速，两方向通过相同时间联系。', '先写竖直落地条件求时间，再代回水平位移。', r`x=u\cos\theta\,t,\qquad y=u\sin\theta\,t-\frac12gt^2`, '定义发射点高度与目标高度；取正的物理时间，再判断是否存在障碍或范围限制。', r`同高度起落时飞行时间为 \(\frac{2u\sin\theta}{g}\)，但高台落地需要重新解竖直方程。`, '最高点竖直速度为零，水平速度通常不为零；不同落地高度不能直接套同高度射程公式。'),
      t('Connected particles and constraints', '连接体与几何约束', '连接体各自满足牛顿方程，绳长等几何约束再联系它们的位移、速度和加速度。', '先由约束说明加速度关系，再联立各物体受力方程。', r`T-m_1g=m_1a,\qquad m_2g-T=m_2a\quad\text{for an ideal fixed-pulley pair}`, '为两个物体选择与实际运动一致的正方向；若有可动滑轮，先写完整绳长关系。', '例如固定光滑滑轮两侧用不可伸长轻绳相连时，两物体加速度大小相等、方向相反。', '有可动滑轮时加速度大小可能不同；不能因看见同一根绳就直接设全部物体同加速度。'),
      t('Friction and limiting equilibrium', '摩擦与极限平衡', '静摩擦按维持平衡的需要取值，只有将要滑动时才达到模型给定的上限。', '静摩擦满足不等式，极限或滑动模型下才使用等号。', r`|F|\le\mu R`, '先不预设极限，按可能滑动方向写摩擦方向；求所需摩擦再与上限比较。', r`水平面上重物受到较小水平拉力时，静摩擦可恰好等于拉力，而不必恒为 \(\mu mg\)。`, '支持力未必等于重力；倾斜拉力、法向加速度或其他接触会改变摩擦上限。'),
    ],
    exercises: [
      q('pulley-pair', 'An ideal pulley pair', r`Particles of masses \(m\) and \(2m\) are joined by a light inextensible string over a smooth fixed pulley. They start from rest with the string taut. (i) Find the acceleration and tension. (ii) Find the time for the heavier particle to descend a distance \(h\), before either particle meets an obstruction.`, '分别给两物体写牛顿第二定律，再利用同大小加速度。', [r`Take the heavier particle downward and the lighter upward as positive. Then \(2mg-T=2ma\) and \(T-mg=ma\). Adding gives \(a=\frac g3\), and substitution gives \(T=\frac{4mg}3\).`, r`The acceleration is constant. From \(h=\frac12at^2\), obtain \(t=\sqrt{\frac{6h}{g}}\). This model applies only while the string remains taut and the motion is unobstructed.`]),
      q('projectile-range', 'Range from components', r`A projectile is launched at speed \(u\) at angle \(0<\theta<\frac\pi2\) above horizontal and lands at its initial height. Ignore air resistance. (i) Derive its range. (ii) Maximise the range over \(\theta\). (iii) Find the maximum height for that optimal angle.`, '从竖直分量求非零落地时间，再回到水平分量。', [r`The vertical displacement is \(u\sin\theta\,t-\frac12gt^2\). Its positive zero is \(t=\frac{2u\sin\theta}{g}\). Hence \(R=\frac{2u^2\sin\theta\cos\theta}{g}=\frac{u^2\sin2\theta}{g}\).`, r`The range is largest at \(\theta=\frac\pi4\), giving \(R_{\max}=\frac{u^2}g\).`, r`The peak occurs when vertical velocity is zero, so \(H=\frac{u^2\sin^2\theta}{2g}=\frac{u^2}{4g}\) at the optimal angle.`]),
    ],
  },
  'mechanics/statics': {
    bullets: [
      t('Force balance and moments', '力平衡与力矩', '刚体静止既需要合力为零，也需要绕任一点的总力矩为零，力矩臂必须垂直于力的作用线。', '选择能消去未知反力的取矩点，通常能减少代数。', r`\sum\mathbf F=\mathbf0,\qquad\sum M_O=0`, '明确每个力的作用点与方向，统一顺逆时针符号，再配合分方向受力平衡。', r`例如水平杆上的竖直力，力矩大小为力乘水平距离；斜力则需取垂直力臂或先分解。`, '合力为零仍可能有力偶导致转动；不能将沿杆距离直接用作任意方向力的力臂。'),
      t('Toppling versus sliding', '倾覆与滑动的先后', '物体失稳可能来自摩擦不足，也可能来自支持力作用点移到边缘，两种临界条件需要分别比较。', '倾覆时关于接触边缘取矩；滑动时检查所需摩擦达到上限。', r`F_{\mathrm{required}}\le\mu R\quad\text{while static contact is possible}`, '分别计算滑动和倾覆的临界外力，取先达到者；核对各自假设是否保持。', '例如水平推长方体时，推力施加得越高，绕底边的倾覆力矩越大，可能在滑动前翻倒。', '不能同时强制滑动极限与倾覆极限成立，除非参数恰好使两者同步。'),
      t('Composite centres of mass', '组合体与质点系重心', '把各部分质量及重心位置加权平均，可计算组合物体的整体重心；孔洞可按被移除质量处理。', '均匀相同密度物体可用长度、面积或体积代替对应质量权重。', r`\bar{\mathbf r}=\frac{\sum_i m_i\mathbf r_i}{\sum_i m_i}`, '选统一原点，将每部分重心写成坐标；挖孔时从原总质量和一阶矩中同时减去。', r`质量一与三的质点位于零与四处，整体重心为 \(\frac{1\cdot0+3\cdot4}{4}=3\)。`, '几何中心只在密度与对称条件合适时等于重心；不同密度部分不能只按面积平均。', 'STEP 3'),
      t('Centres of mass by integration', '积分求重心', '连续物体的一阶质量矩可以用薄条或薄片积分，先把微元质量与其重心写准确。', '分母是总质量，分子是位置乘质量微元的积分。', r`\bar x=\frac{\int x\,dm}{\int dm},\qquad\bar y=\frac{\int y\,dm}{\int dm}`, '对曲线下均匀薄片取竖条，其重心高度为条高的一半；旋转体则使用圆盘面积作质量权重。', r`零到 a 的均匀细杆有 \(dm=\rho\,dx\)，重心为 \(\frac{\int_0^a x\,dx}{a}=\frac a2\)。`, '薄片的面积微元与旋转体体积微元不同；薄条重心不能放在其顶端。', 'STEP 3'),
    ],
    exercises: [
      q('supported-rod', 'A loaded supported rod', r`A uniform horizontal rod of length \(L\) and weight \(W\) is supported vertically at both ends. A particle of weight \(2W\) is placed a distance \(\frac L3\) from the left end. (i) Find the two reactions. (ii) Check that both contacts can remain in compression.`, '对左端取矩先求右端反力，再用竖直合力平衡。', [r`Taking moments about the left end gives \(R_RL=W\frac L2+2W\frac L3\), so \(R_R=\frac{7W}6\).`, r`Vertical balance gives \(R_L+R_R=3W\), hence \(R_L=\frac{11W}6\). Both reactions are positive, so the assumed upward support contacts are possible.`]),
      q('triangular-centroid', 'A triangular lamina by integration', r`A uniform lamina occupies \(0\le x\le a\), \(0\le y\le x\), where \(a>0\). (i) Find its area. (ii) Use vertical strips to find both coordinates of its centre of mass.`, '每条竖条面积为横坐标乘宽度，条重心高度为横坐标的一半。', [r`Its area is \(A=\int_0^a x\,dx=\frac{a^2}2\). Constant surface density cancels from each centroid ratio.`, r`The x-moment is \(\int_0^a x\cdot x\,dx=\frac{a^3}3\), so \(\bar x=\frac{2a}3\).`, r`A strip has centroid height \(\frac x2\), so its y-moment is \(\int_0^a\frac x2\cdot x\,dx=\frac{a^3}6\). Thus \(\bar y=\frac a3\).`], false, 'STEP 3'),
    ],
  },
  'mechanics/energy': {
    bullets: [
      t('Work and instantaneous power', '功与瞬时功率', '力沿位移方向的分量做功，瞬时功率是力与速度的点积，反向阻力做负功。', '功使用沿路程积分的切向力，功率使用当前速度。', r`W=\int\mathbf F\cdot d\mathbf r,\qquad P=\mathbf F\cdot\mathbf v`, '先判断力是否恒定与平行位移；有夹角取对应分量，变力按路径积分。', r`水平恒力 10 牛顿推动物体 3 米做功 30 焦耳；同方向速度 2 米每秒时功率为 20 瓦。`, '功不是力乘时间；摩擦功通常为负，发动机功率还需区分输入功率与机械输出。'),
      t('Conservative energy and dissipation', '机械能与耗散', '动能变化等于总功；把重力和弹性力写成势能后，只将其他非保守力的功放在能量方程右侧。', '能量守恒需要说明没有被忽略的外界做功或耗散。', r`\Delta\left(\frac12mv^2+V\right)=W_{\mathrm{nonconservative}}`, '统一势能零点，列初末状态；摩擦或阻力造成的耗散必须计入。', r`无阻力从静止下降高度 h，满足 \(\frac12mv^2=mgh\)，故 \(v^2=2gh\)。`, '碰撞即使动量守恒，机械能也未必守恒；不能把所有过程都强制同时守恒。'),
      t('Momentum and isolated collision systems', '动量与碰撞系统', '相互作用期间内部力成对抵消，但只有沿所研究方向外界总冲量可忽略时，总动量才守恒。', '先选系统与方向，再判断外冲量是否可忽略。', r`\sum_i m_i u_i=\sum_i m_i v_i\quad\text{when external impulse is negligible}`, '使用带符号速度；选择碰撞前后紧邻的状态，避免将持续重力作用阶段混入。', r`质量相等的两物体在一维完全弹性碰撞中可以交换速度，但这是由两条方程推导的特殊结果。`, '系统受外界显著冲量时不能守恒该方向动量；速度方向变化不能仅用速率代替。'),
      t('Direct impacts and restitution', '正碰与恢复系数', '恢复系数把碰撞后的分离相对速度与碰撞前的接近相对速度联系起来，再结合动量方程解速度。', '恢复系数用于接触法向的相对速度，普通被动碰撞通常在零到一之间。', r`v_2-v_1=e(u_1-u_2)\quad(u_1>u_2\text{ at approach})`, '先固定统一正方向，再检查碰后是否分离；连续碰撞每次更新速度与是否会再次接近。', r`物体正碰静止固定墙时，法向速度反向且大小变为碰前的 e 倍。`, '恢复系数不是动能比；完全非弹性正碰的零恢复系数表示相同法向速度。'),
      t('Impulse and smooth oblique impacts', '冲量与光滑斜碰撞', 'STEP 3 斜碰撞将速度分解为法向与切向；光滑接触不产生切向冲量。', '法向用恢复系数，切向在无切向冲量时保持；冲量等于动量改变量。', r`\mathbf J=m(\mathbf v-\mathbf u)`, '在碰撞面建立法切坐标，分别求碰后分量，再合成速度或偏转角。', r`对静止光滑墙，入射法向分量 u 变为反向的 eu，切向分量保持原值。`, '墙的冲量会改变粒子的动量，不能单独对粒子套总动量守恒；粗糙接触的切向分量未必保持。', 'STEP 3'),
    ],
    exercises: [
      q('direct-impact', 'Restitution with unequal masses', r`On a smooth line, mass \(m\) moves at speed \(u>0\) and strikes a stationary mass \(2m\). Their coefficient of restitution is \(0\le e\le1\). (i) Find both final velocities. (ii) When does the first particle reverse? (iii) Find the kinetic energy lost.`, '联立总动量与分离相对速度，再计算前后动能差。', [r`Write the velocities as \(v_1,v_2\) in the original direction. Momentum gives \(v_1+2v_2=u\), and restitution gives \(v_2-v_1=eu\). Hence \(v_1=\frac{(1-2e)u}3\), \(v_2=\frac{(1+e)u}3\).`, r`The first particle reverses exactly when \(e>\frac12\); at equality it stops.`, r`Substitution into \(\frac12mu^2-\frac12mv_1^2-mv_2^2\) gives \(\frac13mu^2(1-e^2)\), which is nonnegative for the stated range.`]),
      q('oblique-wall', 'Oblique impact with a smooth wall', r`A particle of mass \(m\) strikes a fixed smooth wall at speed \(v\), making angle \(0\le\theta<\frac\pi2\) with the inward normal. The coefficient of restitution is \(0\le e\le1\). (i) Find the normal and tangential speed components after impact. (ii) Find its final speed and the impulse magnitude.`, '沿墙的分量不受冲量；法向分量反向缩小。', [r`Before impact the components have magnitudes \(v\cos\theta\) and \(v\sin\theta\). After impact the normal component is directed away from the wall, with magnitude \(ev\cos\theta\), while the tangential component is unchanged.`, r`The final speed is \(v\sqrt{e^2\cos^2\theta+\sin^2\theta}\). The impulse has only a normal component and magnitude \(m(1+e)v\cos\theta\).`], false, 'STEP 3'),
    ],
  },
  'mechanics/elasticity': {
    bullets: [
      t('Hooke law and natural length', '胡克定律与原长', '弹力由相对原长的伸长量决定，弹性模量与弹簧刚度不同，二者通过原长联系。', '伸长量等于当前长度减原长；原长不是当前长度。', r`T=kx=\frac\lambda l x`, '先标原长与当前长度，统一单位后计算伸长；说明是可压缩弹簧还是只能拉的弹性绳。', r`原长 2 米、弹性模量 10 牛顿的绳伸长 0.2 米，张力为 1 牛顿。`, '弹性绳在缩短到原长以下会松弛，不应继续给负张力；弹簧的压缩模型需题目允许。'),
      t('Elastic potential energy from work', '由功得到弹性势能', '弹力随伸长增加，所以储能要对伸长积分，而不是用末端弹力乘全部位移。', '线性弹性储能是末端张力乘伸长的一半。', r`E=\frac12kx^2=\frac{\lambda x^2}{2l}`, '先确认线性范围和自然状态零势能；与重力势能和动能一起写初末总能。', r`例如刚度 4 牛顿每米的弹簧伸长半米，储能为 \(\frac12\cdot4\cdot(\frac12)^2=\frac12\) 焦耳。`, '不能把势能误写成张力乘伸长；有初始预伸长时要用两状态储能之差。'),
      t('Taut and slack phases', '绷紧与松弛的分段', '弹性绳只有长度超过原长时才有张力，跨过原长后运动方程和势能形式需要切换。', '先找阶段边界，在边界匹配位置与速度。', r`T=\begin{cases}kx&x>0,\\0&x\le0\end{cases}\quad\text{for an ideal elastic string}`, '以伸长为变量记录运动，先假设某段绷紧并检查结果；到零伸长时决定是否进入松弛段。', '例如悬挂弹性绳的粒子向上运动超过自然长度位置后，继续运动时可能只受重力。', '不能把弹性绳压缩当作弹簧反推；松弛后仍沿用有张力的方程会给错误转折点。'),
      t('Equilibrium and equivalent stiffness', '平衡与等效刚度', '静态伸长由力平衡求出，组合弹簧的等效关系可从共同位移或共同张力直接推导。', '串联同力、伸长相加；并联同伸长、弹力相加。', r`\frac1{k_{\mathrm{series}}}=\frac1{k_1}+\frac1{k_2},\qquad k_{\mathrm{parallel}}=k_1+k_2`, '先画连接方式并列约束，再推导等效刚度；竖直平衡时以向下伸长抵消重力。', r`两个相同刚度 k 的轻弹簧串联，等效刚度为 \(\frac k2\)，而并联为 \(2k\)。`, '静态平衡位置不等于从自然长度释放的最大伸长；振荡方程和周期的系统学习列在 STEP 3。'),
    ],
    exercises: [
      q('elastic-vertical', 'Equilibrium versus maximum extension', r`A mass \(m\) hangs from a light vertical elastic string of natural length \(l\) and modulus \(\lambda\). (i) Find the equilibrium extension. (ii) It is instead released from rest when the string is just taut at natural length. Find the first maximum extension, assuming Hooke's law remains valid.`, '平衡用力，最大伸长用从释放点到转折点的能量。', [r`At equilibrium, \(\frac\lambda l x=mg\), so \(x_{\mathrm{eq}}=\frac{mgl}{\lambda}\).`, r`At the first maximum extension the speed is zero. Loss of gravitational potential equals elastic energy: \(mgx=\frac{\lambda x^2}{2l}\). The nonzero turning-point solution is \(x_{\max}=\frac{2mgl}{\lambda}=2x_{\mathrm{eq}}\).`]),
      q('series-springs', 'Deriving a series stiffness', r`Two light springs of stiffnesses \(k_1,k_2>0\) are connected in series and pulled with tension \(F\). (i) Derive the effective stiffness. (ii) For \(k_1=k_2=k\), find the total extension and total elastic energy.`, '串联中两弹簧受同样张力，伸长和能量分别相加。', [r`The extensions are \(x_1=\frac F{k_1}\) and \(x_2=\frac F{k_2}\). Thus \(x=F(\frac1{k_1}+\frac1{k_2})\), so \(k_{\mathrm{eff}}=\frac{k_1k_2}{k_1+k_2}\).`, r`For equal stiffnesses, \(x=\frac{2F}k\). The total energy is \(2\cdot\frac12k(\frac Fk)^2=\frac{F^2}k\), also equal to \(\frac12 k_{\mathrm{eff}}x^2\).`]),
    ],
  },
  'mechanics/further-motion': {
    bullets: [
      t('Radial acceleration and tangential change', '径向加速度与切向变化', '圆周运动即使速率恒定，速度方向仍持续改变；变速时还需切向加速度。', '向心力是实际各力径向合力的名称，不是额外添加的一种力。', r`a_r=\frac{v^2}r=r\omega^2,\qquad a_t=\frac{dv}{dt}`, '选朝圆心为径向正向，分解已有重力、张力或支持力，再按径向牛顿方程求解。', r`匀速水平圆周运动可由绳张力提供向心合力，但不能在张力之外再画一根向心力。`, '匀速只说明切向加速度为零；径向加速度仍非零，且朝圆心。', 'STEP 3'),
      t('Vertical circles and contact constraints', '竖直圆与接触限制', '能量确定不同高度的速率，径向方程决定支持力或张力，物理接触还要求其不为负。', '算出速率后必须检查支持力或张力的允许符号。', r`\frac12mv^2+mgh=\text{constant}\quad\text{for smooth constrained motion}`, '以角度描述高度和重力径向分量，求支持力表达式后检查全程最小值。', r`在竖直圆内侧的最高点，重力与向下支持力合成径向力，故 \(mg+N=\frac{mv^2}r\)。`, '能到达某高度不保证全过程保持接触；若算出负支持力，应在更早位置改变运动模型。', 'STEP 3'),
      t('Simple harmonic motion about equilibrium', '平衡位置附近的简谐运动', '把位移从平衡位置开始计量，若加速度与位移反向且成正比，就得到简谐运动。', '简谐方程中的位移相对平衡位置，角频率平方为正。', r`\ddot x=-\omega^2x,\qquad x=A\cos\omega t+B\sin\omega t`, '由受力方程找平衡位置再平移坐标，使用初始位移与速度确定常数。', r`光滑水平弹簧振子满足 \(m\ddot x=-kx\)，角频率为 \(\sqrt{\frac km}\)，周期为 \(2\pi\sqrt{\frac mk}\)。`, '竖直弹簧的自然长度位置通常不是平衡位置；小摆简谐近似还需小角条件。', 'STEP 3'),
      t('Variable forces and velocity as a position function', '变力与速度位置关系', '力若由位置决定，用速度乘速度对位置的导数代替加速度，可以减少一个时间变量。', '选择自变量要匹配力的给定方式，同时追踪速度方向。', r`a=\frac{dv}{dt}=v\frac{dv}{dx}`, '按力是时间、速度还是位置的函数选择方程；求速率平方后结合初值恢复方向。', r`例如 \(m v\frac{dv}{dx}=-kx\) 积分得到 \(\frac12mv^2+\frac12kx^2=C\)。`, '把速度当位置函数需要在合适运动分支上解释；转向后符号与参数化可能要重新处理。', 'STEP 3'),
      t('Damped oscillations and root types', '阻尼振动与根型', '线性阻力加入弹簧运动后得到二阶方程，辅助根决定振荡、临界或不振荡的衰减方式。', '正阻尼的自由振动能量随时间减少。', r`m\ddot x+c\dot x+kx=0\quad(m,k>0,\ c>0)`, '比较判别式与零，写对应解型；用初始条件和实际量纲检查指数与频率。', r`当 \(c^2<4mk\) 时，解为指数衰减包络乘正弦余弦组合，阻尼频率小于无阻尼角频率。`, '有阻尼时机械能不守恒；非振荡并不意味着物体立即停止或始终不越过平衡点。', 'STEP 3'),
    ],
    exercises: [
      q('vertical-loop', 'Maintaining contact around a loop', r`A particle moves inside a smooth vertical circular track of radius \(a\), with speed \(u\) at the bottom. (i) Find its squared speed at the top. (ii) Find the least \(u\) allowing it to complete the loop while maintaining contact. Justify why the top is the limiting point.`, '能量提供高度与速率关系；径向方程再给支持力，不能只检查顶点速度为实数。', [r`The top is \(2a\) above the bottom, so energy gives \(v_{\mathrm{top}}^2=u^2-4ga\).`, r`At the top, \(mg+N=\frac{mv_{\mathrm{top}}^2}a\). Thus contact requires \(u^2\ge5ga\), and the threshold is \(u=\sqrt{5ga}\).`, r`For angle \(\phi\) measured from the downward radius, \(v^2=u^2-2ga(1-\cos\phi)\). The radial equation gives \(N=\frac{mu^2}a-2mg+3mg\cos\phi\), minimised at the top. Hence the top condition ensures nonnegative contact force throughout; equality is the limiting case.`]),
      q('horizontal-oscillator', 'A horizontal spring oscillator', r`A particle of mass \(m\) is attached to a spring of stiffness \(k\) on a smooth horizontal line. It is released from rest at displacement \(A>0\) from equilibrium. (i) Find its displacement. (ii) Find the speed and first positive time when its displacement is \(\frac A2\).`, '由初值选择余弦解，再通过相位或能量求速度。', [r`The equation is \(m\ddot x=-kx\). With \(\omega=\sqrt{\frac km}\), the initial conditions give \(x=A\cos\omega t\).`, r`The first time with \(x=\frac A2\) has \(\omega t=\frac\pi3\), so \(t=\frac\pi{3\omega}\). The speed is \(A\omega\sin\frac\pi3=\frac{\sqrt3}2A\omega\).`]),
    ],
  },
};
